import{_ as t,o,c as r,ag as a}from"./chunks/framework.BIas3y6W.js";const u=JSON.parse('{"title":"Week 10 — Servers & Deployment","description":"","frontmatter":{"source":"weeks/10-servers-and-deployment/README.md"},"headers":[],"relativePath":"weeks/10-servers-and-deployment/index.md","filePath":"weeks/10-servers-and-deployment/index.md"}'),s={name:"weeks/10-servers-and-deployment/index.md"};function i(n,e,l,h,d,c){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="week-10--servers--deployment" tabindex="-1">Week 10 — Servers &amp; Deployment <a class="header-anchor" href="#week-10--servers--deployment" aria-label="Permalink to &quot;Week 10 — Servers &amp; Deployment&quot;">​</a></h1><blockquote><p>Shipped means a live URL; safe means evidence that the key never left the server.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before Studio A</strong> (≤30 min)</td><td>Read this page. Create a free <strong>Vercel</strong> account (vercel.com, Hobby plan, sign in with GitHub; no card). Check that your week 9 micro-app answers a question in your Codespace and is committed and synced, with no <code>.env</code> on github.com</td></tr><tr><td><strong>Studio A</strong></td><td>Recap · talk: serverless functions, deploying, one request format for many providers, proving a secret stays secret · live demo: a deleted key is still in history · lab: deploy to Vercel and check the production URL, the provider-swap drill · checkpoint share</td></tr><tr><td><strong>Studio B</strong></td><td>Show and tell · lab: prove the key is secret (DevTools, and a secret scan that also checks your git history) · mini-lesson: a server route that calls a public API needing no key · project time: your tests, a pitch check · debrief · exit ticket</td></tr><tr><td><strong>Due before next week&#39;s Studio A</strong></td><td>Default 11:59 pm the night before. <strong>Micro-app due:</strong> live, with its production URL and a screenshot on Canvas · README section &quot;Where the key lives and who can read it&quot; (🔴 AI off) · validation tests you wrote yourself · hidden-costs checklist · <code>PROMPTS.md</code> · <strong>capstone pitch on Canvas, due earlier: 72 hours before week 11 Studio A</strong></td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: Copilot Chat in Ask mode for finishing your app and explaining code · 🟡 AI limited: your validation tests (AI may explain an error; you write them), the pitch (AI may critique it; you write it) · 🔴 AI off: any step with <code>.env</code> or a key on screen, proving the key is secret, &quot;Where the key lives and who can read it&quot;, the exit ticket. <strong>Never:</strong> a key in any AI tool</td></tr><tr><td><strong>Must read</strong></td><td>This page, <a href="./lab.html">Week 10 Lab — Ship it, prove it, call a public API</a>, <a href="./homework.html">Week 10 Homework — Ship the micro-app, test it, pitch the capstone</a></td></tr><tr><td><strong>Look up when needed</strong></td><td><a href="https://github.com/Boyu-Zhang-UOI/vc101-micro-app-starter/blob/main/README.md" target="_blank" rel="noreferrer">AI micro-app starter</a> · <a href="./../../projects/ai-micro-app.html">AI Micro-app brief</a> · <a href="./../../projects/capstone.html#the-pitch">Capstone pitch template</a> · <a href="./../../resources/troubleshooting.html#deploying-to-vercel">Troubleshooting: deploying to Vercel</a> · <a href="./../../resources/troubleshooting.html#i-committed-a-secret">I committed a secret</a> · <a href="./../../TOOLS.html">Tool Handout</a> · <a href="./../../resources/glossary.html">Glossary</a></td></tr><tr><td><strong>Minimum to keep up</strong></td><td>Your capstone pitch is submitted on time. Week 11 starts from it. A micro-app that isn&#39;t live yet can catch up in office hours; the pitch can&#39;t wait</td></tr><tr><td><strong>Time</strong></td><td>Studios 2.5 h · outside about 6 h: prep 30 min, homework core about 3 h, project build time about 2 h, <code>PROMPTS.md</code> about 30 min</td></tr></tbody></table><p>This week finishes the <a href="./../../projects/ai-micro-app.html">AI micro-app</a> you started in <a href="./../09-apis-and-secrets/">week 9</a>: now it goes live.</p><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li>Explain what a serverless function is, and what changes between your Codespace and a production URL.</li><li>Deploy a Node.js app to Vercel, set its environment variables there, and say when to redeploy.</li><li>Switch AI providers by changing configuration only, and explain why that works.</li><li>Prove your key is not in the browser or in your git history, and explain why a deleted file isn&#39;t gone.</li><li>Respond to a leaked key in the right order: revoke, replace, redeploy.</li><li>Read and change a server route that calls a public API, with input checks, a time limit and friendly errors.</li><li>Write automated tests that prove your server&#39;s input check holds, and show that they can fail.</li><li>List the hidden costs of a &quot;free&quot; app.</li></ol><h2 id="before-class" tabindex="-1">Before class <a class="header-anchor" href="#before-class" aria-label="Permalink to &quot;Before class&quot;">​</a></h2><ul><li>☐ Your micro-app answers a question in your Codespace, and its repository is in your <strong>personal</strong> account and <strong>public</strong> (Vercel&#39;s free plan can&#39;t deploy private repositories owned by an organization).</li><li>☐ A free <strong>Vercel</strong> account (vercel.com, Hobby plan, sign in with GitHub).</li><li>☐ Your capstone pitch draft from week 9, ready to show a classmate in Studio B.</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>This week you copy your key into a second place: Vercel&#39;s settings. Rule 2 of the <a href="./../../setup/safety-contract.html#2-i-never-paste-secrets-or-other-peoples-data-into-an-ai-tool">Safety Contract</a> still holds: copying between two of your own tools is fine; pasting into an AI chat, an issue or a commit is not.</p></div><h2 id="studio-agenda" tabindex="-1">Studio agenda <a class="header-anchor" href="#studio-agenda" aria-label="Permalink to &quot;Studio agenda&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Studio</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Studio A — Learn &amp; build</strong></td><td>Recap · concept talk (<a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-10.html" target="_blank" rel="noreferrer">slides</a>) · live demo · <a href="./lab.html#studio-a--ship-it-75-min">lab</a>: deploy to Vercel, the provider-swap drill · checkpoint share</td></tr><tr><td><strong>Studio B — Workshop</strong></td><td>Show and tell · <a href="./lab.html#studio-b--prove-it-and-call-a-public-api-75-min">lab</a>: prove the key is secret, a public-API route · project time · debrief · exit ticket</td></tr></tbody></table><h2 id="materials" tabindex="-1">Materials <a class="header-anchor" href="#materials" aria-label="Permalink to &quot;Materials&quot;">​</a></h2><ul><li><a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-10.html" target="_blank" rel="noreferrer">Slides</a> · <a href="./lab.html">Lab</a> (with a troubleshooting table) · <a href="./homework.html">Homework</a></li><li>Your micro-app, made from the <a href="https://github.com/Boyu-Zhang-UOI/vc101-micro-app-starter" target="_blank" rel="noreferrer">week 9 starter</a>, whose <a href="https://github.com/Boyu-Zhang-UOI/vc101-micro-app-starter/blob/main/README.md" target="_blank" rel="noreferrer">README</a> has the deploy steps and a Cloudflare Workers fallback</li><li>Shared files: the <a href="./../../projects/ai-micro-app.html">AI Micro-app brief</a>, the <a href="./../../projects/capstone.html">Capstone brief</a></li><li>Glossary: <a href="./../../resources/glossary.html#serverless-function">serverless function</a>, <a href="./../../resources/glossary.html#deploy">deploy</a>, <a href="./../../resources/glossary.html#production-url">production URL</a>, <a href="./../../resources/glossary.html#openai-compatible-api">OpenAI-compatible API</a>, <a href="./../../resources/glossary.html#revoke">revoke</a>, <a href="./../../resources/glossary.html#push-protection">push protection</a></li></ul><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><p>If you are working through this week on your own, read this section, then do the <a href="./lab.html">lab</a>.</p><h3 id="serverless-functions" tabindex="-1">Serverless functions <a class="header-anchor" href="#serverless-functions" aria-label="Permalink to &quot;Serverless functions&quot;">​</a></h3><p>GitHub Pages, home of your earlier projects, only serves files, so it can&#39;t keep a secret. Vercel serves <code>public/</code> <strong>and</strong> turns each file in <code>api/</code> into a <strong>serverless function</strong>: code that runs on Vercel&#39;s computers only when someone calls it. &quot;Serverless&quot; means you don&#39;t manage the server. Locally, <code>npm run dev</code> plays Vercel&#39;s role.</p><h3 id="from-your-codespace-to-a-production-url" tabindex="-1">From your Codespace to a production URL <a class="header-anchor" href="#from-your-codespace-to-a-production-url" aria-label="Permalink to &quot;From your Codespace to a production URL&quot;">​</a></h3><p>To <strong>deploy</strong> is to put your app where others can use it. Vercel makes a new deployment after every push to your main branch, and your <strong>production URL</strong> (ending in <code>.vercel.app</code>) always points at the latest. Vercel never sees your <code>.env</code>: you type the same three settings into its Environment Variables page. They reach only <strong>new</strong> deployments, so after changing one you redeploy.</p><h3 id="one-format-many-providers" tabindex="-1">One format, many providers <a class="header-anchor" href="#one-format-many-providers" aria-label="Permalink to &quot;One format, many providers&quot;">​</a></h3><p>Gemini, Groq, OpenRouter, Cloudflare and Ollama all accept the &quot;OpenAI-compatible&quot; request format, so the starter switches provider when you change three settings (<code>LLM_BASE_URL</code>, <code>LLM_API_KEY</code>, <code>LLM_MODEL</code>). That is your insurance when a free tier changes.</p><h3 id="prove-it-dont-assume-it" tabindex="-1">Prove it, don&#39;t assume it <a class="header-anchor" href="#prove-it-dont-assume-it" aria-label="Permalink to &quot;Prove it, don&#39;t assume it&quot;">​</a></h3><p>&quot;I think the key is safe&quot; isn&#39;t evidence. Look at the live site the way a visitor would (DevTools), and scan your files <strong>and your whole git history</strong> (<code>npm run check:secrets</code>): deleting a file doesn&#39;t delete it from history. A clean scan is strong evidence, not a guarantee: it finds only the key formats it knows.</p><h3 id="if-a-key-leaks-revoke-it-first" tabindex="-1">If a key leaks, revoke it first <a class="header-anchor" href="#if-a-key-leaks-revoke-it-first" aria-label="Permalink to &quot;If a key leaks, revoke it first&quot;">​</a></h3><p>If a key lands in a commit, a chat or a screenshot, assume it&#39;s been copied: bots search public repositories for keys. <strong>Revoke</strong> it on the provider&#39;s site (the only step that stops misuse), make a new one, put it in <code>.env</code> and in Vercel, and redeploy. Cleaning the history comes after.</p><h3 id="calling-someone-elses-api" tabindex="-1">Calling someone else&#39;s API <a class="header-anchor" href="#calling-someone-elses-api" aria-label="Permalink to &quot;Calling someone else&#39;s API&quot;">​</a></h3><p>A capstone can fetch live data from a public service: weather, books, public holidays. Even when it needs no key, call it from a server route that checks the input, sets a time limit, turns failures into friendly messages and sends the page only what it needs. If the service later needs a key, the right place is ready.</p><h3 id="tests-prove-the-server-check" tabindex="-1">Tests prove the server check <a class="header-anchor" href="#tests-prove-the-server-check" aria-label="Permalink to &quot;Tests prove the server check&quot;">​</a></h3><p>The server&#39;s input check protects your quota. Your own automated tests prove it holds at your limit every time you run <code>npm test</code>, including after an agent edits your code in week 11. A test that has never failed might test nothing, so you break the code once on purpose and watch it fail.</p><h2 id="understanding-check" tabindex="-1">Understanding check <a class="header-anchor" href="#understanding-check" aria-label="Permalink to &quot;Understanding check&quot;">​</a></h2><p>At the end of Studio B you complete the week 10 exit ticket (🔴 AI off). Expect questions on where the key lives for the live site, what to do if you committed a key and then deleted it, and what can go wrong when your route calls someone else&#39;s API. One question looks back at your week 8 Project 1 final: a function you wrote yourself, and what one of its tests checks. Exit tickets are graded on completion, not correctness.</p><h2 id="homework" tabindex="-1">Homework <a class="header-anchor" href="#homework" aria-label="Permalink to &quot;Homework&quot;">​</a></h2><p>Details and the checklist are in <a href="./homework.html">Week 10 Homework — Ship the micro-app, test it, pitch the capstone</a>.</p><ul><li><strong>Core (required):</strong> your <strong>capstone pitch</strong> (<a href="./../../projects/capstone.html#the-pitch">template</a>), due 72 hours before week 11 Studio A; the micro-app live, with a screenshot; at least two validation tests you write yourself; &quot;Where the key lives and who can read it&quot; (🔴 AI off); a hidden-costs checklist; <code>PROMPTS.md</code>.</li><li><strong>Stretch (optional):</strong> your own rate-limit (429) message; a whole-route test; Cloudflare Workers; the weather on your page.</li></ul><p>The micro-app is graded once, with the <a href="./../../assessment/rubrics.html#ai-micro-app">AI micro-app rubric</a>, which includes the pitch.</p><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>What to do</th></tr></thead><tbody><tr><td>Vercel won&#39;t import your repo</td><td>Vercel&#39;s free plan can&#39;t deploy <strong>private</strong> repositories owned by an organization: keep the repo in your <strong>personal</strong> account. Otherwise use the <a href="https://github.com/Boyu-Zhang-UOI/vc101-micro-app-starter/blob/main/README.md#cloudflare-workers-fallback-optional" target="_blank" rel="noreferrer">Cloudflare Workers fallback</a></td></tr><tr><td>Vercel is down</td><td>Do Part B1 against your local server and deploy at home, or use the Cloudflare Workers fallback</td></tr><tr><td>Your provider returns <code>429</code> or is down</td><td>Do the provider-swap drill now, locally and on Vercel</td></tr><tr><td>The public API in Studio B is down</td><td>Read the route against the sample response in the lab; try the real call later</td></tr><tr><td>Codespaces quota used up</td><td>Stop old codespaces at github.com/codespaces, or use the optional <a href="./../../setup/local-setup.html">local setup</a></td></tr><tr><td>Copilot credits ran out</td><td>Keep going without it: no lab step needs AI (<a href="./../../resources/troubleshooting.html#i-ran-out-of-free-credits">I ran out of free credits</a>)</td></tr></tbody></table><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>Vercel Docs, <a href="https://vercel.com/docs/functions/functions-api-reference" target="_blank" rel="noreferrer">Functions API reference</a>: the <code>fetch</code> handler your <code>api/ask.js</code> uses.</li><li>GitHub Docs, <a href="https://docs.github.com/en/code-security/secret-scanning/introduction/about-push-protection" target="_blank" rel="noreferrer">About push protection</a>: how GitHub can block a pushed secret.</li><li>GitGuardian, <a href="https://blog.gitguardian.com/the-state-of-secrets-sprawl-2026/" target="_blank" rel="noreferrer">The State of Secrets Sprawl 2026</a>: how and where secrets leak.</li><li>Open-Meteo, <a href="https://open-meteo.com/en/docs" target="_blank" rel="noreferrer">API documentation</a>: the weather API in the Studio B mini-lesson.</li><li>More readings: the <a href="./../../resources/reading-list.html">Reading List</a>.</li></ul>',41)])])}const m=t(s,[["render",i]]);export{u as __pageData,m as default};
